insert into xpms.dim_record_class (record_class, ordinal) values
  ('Work', 1),
  ('Artifact', 2),
  ('Commitment', 3),
  ('Control', 4),
  ('Time', 5);
insert into xpms.dim_record_kind (record_kind, ordinal, definition, definition_of_done, record_class, title_grammar) values
  ('Build', 1, 'An installation or load-in block against a specification.', 'Installed, powered and demonstrated against the specification.', 'Work', 'Imperative verb first. Names the installation act.'),
  ('Rehearsal', 2, 'A run-through before an audience is present.', 'Run-through signed off by the production lead.', 'Work', 'Imperative verb first. Names the run-through act.'),
  ('Shift', 3, 'A staffed crew block with a call and a wrap.', 'Crew called, present and signed out against the approved headcount.', 'Work', 'role · block. The role comes from dim_role, the block from the subtype.'),
  ('Strike', 4, 'A load-out and restoration block.', 'Venue returned to house condition and signed off.', 'Work', 'Imperative verb first. Names the load-out act.'),
  ('Task', 5, 'A unit of work a person performs that ends in a filed outcome.', 'Filed and accepted by the accountable owner.', 'Work', 'Imperative verb first, drawn from the subtype verb set.'),
  ('Training', 6, 'A curriculum session delivered to a named role.', 'Trainee signs off the curriculum checklist.', 'Work', 'Imperative verb first. Names the session delivered.'),
  ('Document', 7, 'A written artifact that exists when the row is done.', 'Delivered, acknowledged and filed to the document store.', 'Artifact', 'Noun phrase naming the artifact that exists when the row is done.'),
  ('Supply', 8, 'A physical or licensed item received against an order.', 'Received, counted and checked against the order.', 'Artifact', 'Noun phrase naming the item received.'),
  ('Booking', 9, 'A reserved resource, space or person.', 'Confirmed in writing and contracted.', 'Commitment', 'Noun phrase naming the reservation.'),
  ('Contract', 10, 'An executed agreement between two parties.', 'Countersigned copies and certificates of insurance on file.', 'Commitment', 'Noun phrase naming the agreement. Progress is carried by record_state, not the title.'),
  ('Payment', 11, 'A movement of money against an approved commitment.', 'Invoice issued and payment received.', 'Commitment', 'Imperative verb first. Names the movement of money.'),
  ('Recruitment', 12, 'A role taken from vacant to filled and credentialled.', 'Role filled, onboarded and credentialled.', 'Commitment', 'Imperative verb first. Names the act of filling the role.'),
  ('Approval', 13, 'A written sign-off that unblocks downstream work.', 'Written approval on file; email is the source of truth.', 'Control', 'Noun phrase naming what is being approved.'),
  ('Compliance', 14, 'A document that must be on file and current.', 'Document on file and current.', 'Control', 'Noun phrase naming the document that must be on file and current.'),
  ('Deadline', 15, 'A date on which something is owed by a party outside the team.', 'The owed item received, or the slip escalated in writing.', 'Control', 'Noun phrase naming the item owed.'),
  ('Decision', 16, 'A choice recorded so it is not relitigated.', 'Decision recorded in the approval log.', 'Control', 'Noun phrase naming the choice to be recorded.'),
  ('Inspection', 17, 'A walk or test that must be passed.', 'Walk passed and the record filed.', 'Control', 'Noun phrase naming the check that must be passed.'),
  ('Permit', 18, 'An instrument issued by an authority having jurisdiction.', 'Issued by the authority and posted on site.', 'Control', 'Noun phrase naming the instrument issued by the authority.'),
  ('Distribution', 19, 'A publish or send action with usage rights.', 'Published and logged with usage rights.', 'Time', 'Noun phrase naming what is published or sent.'),
  ('Event', 20, 'A dated occurrence with attendance.', 'Doors opened and the event ran to the run of show.', 'Time', 'Proper title in title case.'),
  ('Goal', 21, 'A measurable outcome target, not a task.', 'Measured against target at the review date.', 'Time', 'Achieved-state outcome: the result stated as already reached.'),
  ('Meeting', 22, 'A scheduled conversation with a logged outcome.', 'Notes, decisions and dependencies logged.', 'Time', 'Noun phrase naming the conversation.'),
  ('Milestone', 23, 'A zero-duration marker that a named condition is true.', 'The named condition is true; zero duration.', 'Time', 'Completed-state phrase: the condition stated as already true.'),
  ('Report', 24, 'A recurring published output.', 'Delivered to the distribution list and filed.', 'Time', 'Noun phrase naming the publication.'),
  ('Risk', 25, 'A tracked exposure with a mitigation and an owner.', 'Mitigation in place, or the risk formally accepted.', 'Time', 'Noun phrase naming the exposure, not a sentence describing it happening.'),
  ('Timeline', 26, 'A window that child rows roll up into.', 'Every child row closed or explicitly carried forward.', 'Time', 'Noun phrase naming the window.');
