insert into xpms.dim_touchpoint (touchpoint_id, ordinal, sense, brief_element, category, item, base, elevated, premium, optional_upgrades, add_ons, substitutions, venue_zone, event_tier_fit, dept_code, division, tier_code, lifecycle_phase_code, xyz) values
  ('SGT-01', 1, 'Architecture (Sight)', 'Floor Plan', 'Stage Configuration', 'Ground-Level Stage', 'Low-rise 12in deck stage on the sanctuary floor; audience on the same plane; intimate club-floor feel.', '16–24in deck with skirted fascia, monitor wedges, and a defined DJ/performer zone; clear sightline lane.', 'Custom-fabricated floor stage with integrated LED fascia, riser-built DJ altar, and surround standing pit.', 'LED stage-front ribbon; rotating turntable riser', 'DJ booth scenic wrap; B-stage spur', 'Black box flat-floor (no deck)', 'Main Stage & Bar', 'T1–T4', '5000', 'Staging / Stage Systems', '06', 'BLD', 'X'),
  ('SGT-02', 2, 'Architecture (Sight)', 'Floor Plan', 'Stage Configuration', 'Elevated Proscenium Stage', '36–42in elevated stage at the nave head; rental decking, stairs, and pipe-and-drape surround.', '48in stage with hard scenic proscenium frame, side fills, and branded header valance.', 'Architectural elevated stage with sculptural proscenium, integrated LED reveal, and orchestra-style downstage thrust.', 'Motorized reveal curtain; thrust extension', 'Confidence monitor; teleprompter', '360 center stage (in-the-round)', 'Main Stage & Bar', 'T2–T4', '5000', 'Staging / Stage Systems', '06', 'BLD', 'X'),
  ('SGT-03', 3, 'Architecture (Sight)', 'Floor Plan', 'Stage Configuration', '360 Center Stage (In-the-Round)', 'Round 14ft center riser with audience on all sides; ground-supported lighting halo above.', '20ft rotating center stage with circular LED skirt and overhead truss ring with moving lights.', 'Kinetic in-the-round altar with rotating deck, suspended LED halo, and floor projection apron.', 'Rotating deck motor; floor projection ring', 'Aerial rig point for performer', 'Runway / catwalk T-stage', 'Main Stage & Bar', 'T3–T4', '5000', 'Staging / Stage Systems', '06', 'BLD', 'X'),
