insert into xpms.dim_budget_template_rule (field, ordinal, rule) values
  ('Columns', 1, 'Record ID, Project, Event, Location, Zone, Space, Activation, Department, Discipline, Category, Sub-category, Team, Item, Description, URID, Phase, Tier, XYZ, Line Type, Quantity, Rate, Unit Basis, Estimate, Grade 1 Basic, Grade 2 Standard, Grade 3 Premium, Budget, Committed, Forecast, Actual, Variance, Vendor, Line State, Flag, External Notes, Internal Notes, Account Code, Account Name, Tracking 1, Tracking 2, Tax Type, Currency'),
  ('Rows', 2, 'One line per category from tabs 01 to 03, grouped by department and discipline. A budget is a chart of accounts, not a work list'),
  ('Line types', 3, 'Scope, Overhead, Contingency, Fee, Retainer'),
  ('Estimate', 4, '= Grade 2 Standard'),
  ('Budget', 5, '= Estimate; locks at approval'),
  ('Forecast', 6, '= MAX(Budget, Committed)'),
  ('Variance', 7, '= Budget - Actual'),
  ('Rate', 8, '= Estimate / Quantity'),
  ('Contingency', 9, 'Model A: 5% of Grade 2 scope, added on top'),
  ('Aggregates', 10, 'Blank when every input is blank. Never COALESCE to zero'),
  ('XYZ', 11, 'Schema family tag. X Resource: people, teams and companies, locations, inventory (data lists). Y Process: scope, workflows, services, subscriptions (junction tables). Z Timeline: events, activations, logistics (the unified spine).'),
  ('Line State', 12, 'Not started, Quoted, Committed, Invoiced, Paid, Canceled'),
  ('Account Code', 13, 'From tab 31; every category posts to exactly one account'),
  ('Tracking 1', 14, 'Cost center from tab 30'),
  ('Tracking 2', 15, 'Workstream or team');
insert into xpms.dim_change_record (change, ordinal, from_value, to_value, why) values
  ('Department 4000 label', 1, 'Build', 'Environment', 'Three things named Build; 4000xBLD read as Build times Build'),
  ('Gate 1', 2, 'Discover DIS', 'Scope SCP', 'What needs to happen; absorbs Design because scope lock is the design deliverable'),
  ('Gate 2', 3, 'Design DSN', 'Engage ENG', 'Who is going to make it happen; contracting gets its own gate so the silence rule bites'),
  ('Gate 3', 4, 'Advance', 'Advance (redefined)', 'What they need to make it happen; the production sense of the word'),
  ('Gate criteria', 5, '32', '35', 'Remapped to 4.0 gates; G2.ACCOUNTABLE_PARTY, G3.PERMITS_FILED, G3.PO_BASELINE added'),
  ('Ramp-up categories', 6, 'Discover, Design, Advance activities', 'Scope, Engage, Advance activities', 'Gate buckets follow the gates'),
  ('Discipline 6000.53', 7, 'absent', 'Occupancy and Utilities', 'Canon had no home for occupancy cost'),
  ('Record state', 8, 'Cancelled', 'Canceled', 'American English'),
  ('Coordinate short form', 9, '{DepartmentName}x{PHASE}', '{CLASS}x{PHASE_CODE}', 'Canon form'),
  ('Item catalog', 10, '660 canon elements unpriced', '1443 items with 352 priced from the 2.x catalog and 90 touchpoints at three grades', 'Pricing evidence and the experience layer joined to canon on one schema'),
  ('GL chart', 11, 'absent', '44 accounts, 16 cost centers, 291 categories mapped', 'Universal accounting import'),
  ('Record model', 12, 'absent from canon', '26 kinds, 5 classes, kind-scoped subtypes, 9 states', 'The schedule layer XOS adds above the catalog'),
  ('Workforce', 13, 'absent from canon', '61 roles, 22 job titles, 22 counterparty types', 'The people layer'),
  ('XYZ definition', 14, 'Cost behavior', 'Schema family: X Resource, Y Process, Z Timeline', 'A tag that names which table family a thing belongs to'),
  ('Catalog deduplication', 15, '1443 rows', '1211 rows', 'Legacy and gap-fill duplicates folded onto the canon record; price evidence carried across'),
  ('GL ordering', 16, 'Grouped by type', 'Numeric ascending', 'Codes are always in numeric order'),
  ('Chart of accounts', 17, '44 accounts by type', '23 accounts: ledger type x class', 'Account answers what; cost center and URID dimensions answer where and why, matching NetSuite, Xero, QuickBooks and Ramp'),
  ('Cost centers', 18, '16 by department and scope', '6: standing, corporate, one per event', 'Class moved into the account; department cost centers were redundant'),
  ('Item IDs', 19, 'Four shapes by source', '{URID}-{ORG}-{SEQ}', 'Canon grammar for every item; legacy codes and touchpoint IDs move to external_ref'),
  ('Posting line', 20, 'Three export layouts', 'One Universal Posting Line', 'Every platform import is a projection'),
  ('States', 21, 'Six vocabularies', 'One shared core with domain extensions', 'A filter means the same thing on every tab');
insert into xpms.canon_statement (tab, ordinal, item, statement) values
  ('00 Cover', 1, 'Version', 'XOS 4.0 · generated 2026-09-15'),
  ('00 Cover', 2, 'Builds on', 'XPMS 3.0 release candidate canon (SSOT Bible), the 2.x master catalog (pricing evidence), the Experiential Catalog Framework (five-sense touchpoints), and the CSMIA26 build session'),
  ('00 Cover', 3, 'Version rule', 'Major version = grammar change; minor version = element or category additions. 4.0 changes phase grammar and is a major version'),
  ('00 Cover', 4, 'Non-goals held', 'Ten department classes; nine gated phases with ordinals 1 to 9; three acts PLAN BUILD SHOW; URID grammar with no fourth segment; 90-coordinate matrix; Fee and Contingency as line types. No code moves in 4.0'),
  ('00 Cover', 5, 'Grammar change 1', 'Department 4000 is Environment. Code unchanged. Three things had been named Build: a department, gate 5 and a record kind'),
  ('00 Cover', 6, 'Grammar change 2', 'Gates 1 to 3 are Scope, Engage, Advance: what needs to happen, who is going to make it happen, what they need to make it happen. Design folds into Scope because scope lock is the design deliverable. DIS and DSN retire under supersession'),
  ('00 Cover', 7, 'Extension ranges', 'Canon disciplines and categories hold .01 to .49; adopter extensions hold .50 to .99 under their own org. Every extension in this Bible is tagged'),
  ('00 Cover', 8, 'New in 4.0', 'GL chart of accounts and cost centers mapped to every category; merged item catalog with pricing evidence and three grades; record model with 26 kinds; 35 gate criteria; 61 workforce roles; 22 counterparty types; occupancy discipline 6000.53'),
  ('00 Cover', 9, 'Silence rule', 'An absent claim is rank 0 and resolves as a refusal, never as a permissive default. A blank price is unpriced; a zero is a claim. Aggregates of blanks are blank'),
  ('00 Cover', 10, 'Ratification', '3.0 has no named ratifier for a major version, so 4.0 grammar is proposed until one is named. Supersession is data, so reverting is a data change'),
  ('00 Cover', 11, 'Locale', 'American English throughout. record_state Canceled, never Cancelled'),
  ('00 Cover', 12, 'XYZ', 'X Resource (people, teams and companies, locations, inventory: data lists). Y Process (scope, workflows, services, subscriptions: junction tables). Z Timeline (events, activations, logistics: the unified spine). A tag on every item, record and budget line, with its basis stored beside it.'),
  ('00 Cover', 13, 'Naming standard', 'Proper names, taxonomy labels, item names and enum values in Title Case; descriptions and definitions in sentence case, period-terminated. The ampersand is kept in Title Case labels and written as and in sentence-case prose. No em dashes; dimensions as 3 ft x 3 ft 2 in. American English.'),
  ('00 Cover', 14, 'Ordering', 'Every coded list is in numeric order: GL accounts, disciplines, categories, criteria, cost centers, items.'),
  ('21 Identity Doctrine', 1, 'CARDINALITY', 'Many GTINs map to one element. One GTIN maps to at most one element.'),
  ('21 Identity Doctrine', 2, null, 'A 4x8 stage deck panel is ONE element and THREE manufacturers'' GTINs. An org binding table looks 1:1 from the binding side; it is not. This rule is stated verbatim so nobody ''fixes'' the many-to-one into a one-to-one.'),
  ('21 Identity Doctrine', 3, 'CROSSWALK', 'GTIN -> GPC brick -> UNSPSC -> URID. Proposed, human-confirmed, NEVER automatic. The mapping narrows a human''s choice; it does not replace it. Lossy in both directions.'),
  ('23 Silence Rule', 1, 'INSTANCES', null),
  ('23 Silence Rule', 2, '·', null),
  ('23 Silence Rule', 3, '·', null),
  ('23 Silence Rule', 4, '·', null),
  ('23 Silence Rule', 5, '·', null),
  ('23 Silence Rule', 6, 'WHY', null),
  ('23 Silence Rule', 7, 'CEILING', null),
  ('23 Silence Rule', 8, 'FLOOR', null),
  ('23 Silence Rule', 9, 'NOTE', null),
  ('_generated', 1, 'generated_at', '2026-09-15T17:26:34'),
  ('_generated', 2, 'generator', 'build_bible.py'),
  ('_generated', 3, 'sources', 'XPMS_3_0_SSOT_Bible.xlsx; xpms-master-catalog__source_.xlsx; XPMS_Experiential_Catalog_Framework.xlsx; XOS_4.0_Unified_Master_Calendar_3NF_CSMIA26_v13.xlsx'),
  ('_generated', 4, 'departments', '10'),
  ('_generated', 5, 'disciplines', '114'),
  ('_generated', 6, 'categories', '291'),
  ('_generated', 7, 'gate_criteria', '35'),
