insert into xpms.role (role_code, job_title, discipline, rank, job_summary, key_responsibilities, qualifications, physical_requirements, required_certifications, default_clearance_tier, default_radio_channel, flag, notes, source_row, source_status, source_created_by, source_created_at, source_updated_at) values
  ('0000.50.01', 'Chief Executive Officer', 'Governance & Client Relations', 'Executive', 'Overall executive leadership, commercial governance, and client stakeholder management.', 'Direct executive strategy; authorize major expenditures; represent production to partners.', '10+ years executive leadership in large-scale live productions.', 'Standard office & site walkthroughs.', 'Executive Leadership Certification', 'Tier 1 - Executive Master', 'Channel 1 (Emergency)', false, 'Canonical Executive Lead', 2, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('0000.51.01', 'Production Finance Director', 'Commercial and Finance', 'Director', 'Directs overall event fiscal governance, purchase commitments, payroll, and financial closeout.', 'Manage event pro forma, authorize vendor purchase orders, reconcile master production budget.', '8+ years live event production finance and commercial management.', 'Standard office & production trailer environment.', 'CPA or Master in Finance Preferred', 'Tier 1 - Executive Master', 'Channel 1 (Emergency)', false, 'Fiscal Governance Lead', 13, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('1000.50.01', 'Creative Director', 'Programming & Creative Direction', 'Director', 'Visionary oversight for artistic programming, scenic design, and guest creative experience.', 'Lead creative concepts, guide scenic aesthetics, curate artist programming cadence.', '8+ years creative direction in experiential entertainment.', 'Standard site walks across creative zones.', 'Creative Arts Degree or equivalent experience', 'Tier 1 - Executive Master', 'Channel 3 (Site Ops)', false, 'Canonical Creative Lead', 3, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('1000.50.02', 'Event & Programming Director', 'Programming & Creative Direction', 'Director', 'Curates talent lineup, schedules performance blocks, and coordinates talent logistics.', 'Manage talent booking, run-of-show synchronization, artist relations alignment.', '7+ years music industry and festival talent management.', 'Prolonged site presence during show run.', 'Talent Logistics & Artist Relations Certification', 'Tier 1 - Executive Master', 'Channel 3 (Site Ops)', false, 'Canonical Programming Lead', 4, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('1000.51.01', 'Scenic Art Director', 'Scenic and Graphics Production', 'Lead', 'Oversees spatial styling, environmental scenic fabrication, and artistic installation fidelity.', 'Manage scenic fabrication vendors, direct scenic dressing, approve finish materials.', '6+ years theatrical or experiential scenic design and fabrication.', 'Active walking across build environments and scenic shops.', 'OSHA 10, Scenic Design Degree or equivalent', 'Tier 2 - Technical Lead', 'Channel 3 (Site Ops)', false, 'Scenic & Environment Lead', 14, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('2000.50.01', 'Backline Tech / Instrument Specialist', 'Talent Operations', 'Technician', 'Manages backline musical instruments, amplifier rigs, stage tuning, and artist rider fulfillment.', 'Set up drum kits, tune instrument rigs, execute stage changeovers, manage stage backline.', '5+ years concert touring and festival backline technical experience.', 'Able to lift 60 lbs, bend, crouch, and move heavy flight cases.', 'Backline Specialist Certification', 'Tier 2 - Technical Lead', 'Channel 7 (Stage Ops)', false, 'Stage Backline Lead', 15, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('2000.50.02', 'Artist Relations Coordinator', 'Talent Operations', 'Coordinator', 'Coordinates artist on-site arrivals, dressing room hospitality, green room protocol, and escort.', 'Advance rider hospitality, escort talent from transport to green rooms, oversee green room amenities.', '3+ years talent hospitality or artist relations at live events.', 'High mobility across backstage and dressing room corridors.', 'First Aid / CPR, Hospitality Management Degree', 'Tier 2 - Technical Lead', 'Channel 7 (Stage Ops)', false, 'Backstage Artist Care Lead', 16, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('3000.50.01', 'Principal Event Photographer', 'Content Capture', 'Specialist', 'Leads on-site stills photography, red carpet documentation, and real-time social photo delivery.', 'Capture high-resolution show stills, edit daily hero photo packs, coordinate with social team.', '5+ years concert, festival, and live event production photography.', 'Continuous mobility across pit, stage wings, and crowd areas with heavy camera gear.', 'Professional Media Accreditation', 'Tier 2 - Technical Lead', 'Channel 6 (Media & Capture)', false, 'Lead Stills Photographer', 17, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('3000.50.02', 'Lead Cinematographer / Video Shooter', 'Content Capture', 'Specialist', 'Captures 4K cinema footage of live performances, activations, and crowd atmosphere for marketing.', 'Operate gimbal and handheld camera rigs, direct B-roll capture, offload media to DIT.', '5+ years concert documentary and commercial video production.', 'High mobility carrying camera and stabilizer rigs up to 25 lbs.', 'FAA Part 107 (if drone), Cinema Camera Operator Certified', 'Tier 2 - Technical Lead', 'Channel 6 (Media & Capture)', false, 'Lead Live Video Capture', 18, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('3000.50.03', 'Real-Time Social Content Producer', 'Content Capture', 'Coordinator', 'Produces real-time social cutdowns, story coverage, and live stream clips during event run.', 'Edit same-day social reels, publish scheduled story drops, coordinate artist social tags.', '3+ years live event social media publishing and mobile content editing.', 'High mobility throughout audience and VIP activations.', 'Social Content Specialist Certification', 'Tier 2 - Technical Lead', 'Channel 6 (Media & Capture)', false, 'Live Social Channel Producer', 19, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('4000.50.01', 'Structural Carpenter / Build Lead', 'Base Build Delivery', 'Lead Technician', 'Directs modular staging construction, custom scenic carpentry, and timber load-in builds.', 'Lead carpentry build crews, interpret technical CAD elevations, enforce shop safety standards.', '6+ years commercial carpentry or theatrical master carpentry.', 'Able to lift 75 lbs, operate heavy power tools, work at height.', 'OSHA 30, Master Carpenter Certification', 'Tier 2 - Technical Lead', 'Channel 3 (Site Ops)', false, 'Master Scenic Build Lead', 20, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('4000.51.01', 'HVAC & Site Climate Tech', 'Building Systems Maintenance', 'Technician', 'Maintains temporary AC units, tent spot coolers, ductwork runs, and venue air circulation.', 'Monitor cooling loads, fuel portable AC units, troubleshoot duct transitions, balance room temps.', '4+ years temporary climate control and HVAC equipment service.', 'Able to lift 50 lbs, crawl into mechanical plenum spaces, outdoor exposure.', 'EPA Universal HVAC, OSHA 10', 'Tier 2 - Technical Lead', 'Channel 5 (Power & IT)', false, 'Site Environmental Climate Tech', 21, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('5000.50.01', 'Production & Operations Director', 'Production Leadership', 'Director', 'Senior technical director overseeing stage, site ops, logistics, and vendor integration.', 'Oversee multi-stage build, enforce master production schedule, direct site leads.', '10+ years festival technical direction and venue buildout.', 'Able to walk active construction grounds 10+ hrs/day.', 'OSHA 30, Rigging Inspection Certified', 'Tier 1 - Executive Master', 'Channel 3 (Site Ops)', false, 'Canonical Senior Production Lead', 5, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('5000.50.02', 'Master Electrician / Power Lead', 'Power & Utilities', 'Lead Technician', 'Directs site power distribution, generator synchronization, and technical power safety.', 'Calculate load schedules, manage temporary generator banks, balance distribution panels.', '6+ years temporary power distribution for live events.', 'Able to lift 50 lbs, climb ladders, and work outdoors.', 'Licensed Master Electrician, NFPA 70E', 'Tier 2 - Technical Lead', 'Channel 5 (Power & IT)', false, 'Master Power Systems Lead', 6, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('5000.50.03', 'Production Coordinator', 'Production Leadership', 'Coordinator', 'Manages production office logistics, daily crew call sheets, vendor credentials, and radios.', 'Issue daily call sheets, log equipment deliveries, distribute radios and production expendables.', '3+ years live event or festival production office operations.', 'Active walking between production trailers and stage decks.', 'OSHA 10, Event Management Degree', 'Tier 2 - Technical Lead', 'Channel 3 (Site Ops)', false, 'Central Production Office Coordinator', 22, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('5000.51.01', 'Lead Stagehand / Deck Crew Chief', 'Stage Crew', 'Crew Chief', 'Supervises stagehands during equipment load-in, stage turnover, changeovers, and load-out.', 'Direct push crews, organize truck pack loading, enforce deck safety, expedite gear turns.', '5+ years live stage crewing and union/non-union deck supervision.', 'Able to lift 75 lbs, prolonged standing and brisk walking across stage decks.', 'OSHA 10, Forklift Operator Certified', 'Tier 2 - Technical Lead', 'Channel 7 (Stage Ops)', false, 'Lead Stage Deck Crew Chief', 23, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('5000.51.02', 'Head Arena / Festival Rigger', 'Stage Crew', 'Lead Technician', 'Calculates overhead rig loads, supervises motor hangs, truss pinning, and aerial safety.', 'Review engineered rigging plots, inspect wire rope and hardware, supervise high riggers.', '7+ years arena, festival, or theatrical overhead rigging leadership.', 'Comfortable working at extreme heights (60+ ft), full harness mobility, lifting 50 lbs.', 'ETCP Arena Rigging Certified, SPRAT/IRATA Rope Access', 'Tier 2 - Technical Lead', 'Channel 3 (Site Ops)', false, 'Head Overhead Rigging Specialist', 24, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('5000.51.03', 'Lead System Rigger', 'Stage Crew', 'Technician', 'Executes high rigging hangs, bridle points, motor cable runs, and secondary safety tie-offs.', 'Climb steel structures, pull motor chains, attach beam clamps and spansets to engineered points.', '4+ years commercial entertainment high rigging.', 'Working at height, climbing truss and steel beams, heavy physical exertion.', 'ETCP Rigging Apprentice / ETCP Certified, OSHA 10', 'Tier 2 - Technical Lead', 'Channel 3 (Site Ops)', false, 'High Steel Rigger', 25, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('5000.52.01', 'Special Effects / Pyro Lead', 'Production Supply', 'Lead Technician', 'Operates CO2 cryo jets, cold spark machines, atmospheric hazers, and low-lying fog units.', 'Program SFX cue triggers, manage pressurized gas cylinders, enforce fire safety perimeter.', '5+ years theatrical special effects and atmospheric systems operation.', 'Handling heavy gas cylinders (100 lbs with dolly), outdoor and stage exposure.', 'State Pyrotechnic Operator License, NFPA 1126/160 Certified', 'Tier 2 - Technical Lead', 'Channel 7 (Stage Ops)', false, 'Lead SFX & Atmospherics Operator', 26, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('6000.50.01', 'House Manager', 'House Management', 'Manager', 'Manages front of house operations, guest circulation, hospitality, and crowd services.', 'Supervise ushering, coordinate box office and access control, oversee ingress/egress.', '5+ years venue operations and public assembly management.', 'Continuous walking and standing during operating hours.', 'Crowd Management Certification, First Aid / CPR', 'Tier 1 - Executive Master', 'Channel 4 (Exterior Ops)', false, 'Canonical House Ops Lead', 7, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('6000.50.02', 'Site Safety & Security Lead', 'Safety & Security', 'Lead', 'Leads perimeter integrity, crowd safety protocols, emergency egress, and liaison with AHJ.', 'Direct private security deployment, coordinate with local fire/police, enforce security grid.', '7+ years event security management and law enforcement coordination.', 'High mobility across perimeter and venue grounds.', 'OSHA 30, Crowd Control Specialist, CPR/AED', 'Tier 2 - Technical Lead', 'Channel 2 (Security)', false, 'Perimeter & Incident Security', 8, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('6000.50.03', 'VIP Experience Manager', 'House Management', 'Manager', 'Oversees VIP check-in lounge, bottle service coordination, luxury amenities, and guest escorts.', 'Manage VIP host team, coordinate private table allocations, supervise VIP credential gates.', '5+ years luxury hospitality or festival VIP lounge management.', 'Continuous standing and walking across VIP spaces.', 'TIPS / ServSafe Certified, Hospitality Leadership Degree', 'Tier 2 - Technical Lead', 'Channel 4 (Exterior Ops)', false, 'Lead VIP Guest Experience Manager', 27, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('6000.51.01', 'Janitorial & Waste Operations Lead', 'Venue Services', 'Lead', 'Directs ongoing venue cleanliness, restroom maintenance schedules, trash sorting, and recycling.', 'Supervise custodial crews, manage compactor cycles, maintain sanitation supply inventories.', '4+ years large venue or public assembly custodial operations.', 'Continuous physical movement, lifting 50 lbs waste containers.', 'OSHA 10, HazCom Sanitation Certified', 'Tier 3 - Staff / Crew', 'Channel 4 (Exterior Ops)', false, 'Site Cleanliness & Environmental Lead', 28, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('6000.51.02', 'Marshalling Yard & Dock Master', 'Venue Services', 'Manager', 'Controls semi-truck holding yard, freight check-in, load-in dock call times, and traffic flow.', 'Schedule truck dock calls, log bill of lading seals, coordinate forklift unloading sequence.', '6+ years freight logistics, festival marshalling, and transport dispatch.', 'High mobility across trucking yards, concrete staging aprons, all weather conditions.', 'DOT Compliance, CDL Class A Preferred', 'Tier 2 - Technical Lead', 'Channel 4 (Exterior Ops)', false, 'Freight Dispatch & Dock Master', 29, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('6000.52.01', 'Security Supervisor', 'Event Security', 'Supervisor', 'Supervises licensed guard posts, metal detector magnetometers, bag check lanes, and ejections.', 'Deploy security officers, de-escalate patron disturbances, maintain incident dispatch logs.', '5+ years crowd control security supervision and emergency de-escalation.', 'Prolonged standing, high physical readiness in crowd environments.', 'State Security D/G License, First Aid / CPR / AED', 'Tier 2 - Technical Lead', 'Channel 2 (Security)', false, 'Perimeter & Ingress Security Supervisor', 30, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('7000.50.01', 'Front of House Lead / Box Office Manager', 'Front of House', 'Manager', 'Manages main entrance turnstiles, ticket resolution booths, guest service info desks, and ADA access.', 'Supervise ticket scanning teams, resolve ticketing exceptions, enforce ADA accessible routes.', '5+ years venue box office management and guest service leadership.', 'Prolonged standing at entrance gates and patron ingress corridors.', 'Box Office System Certified, Crowd Management Certified', 'Tier 2 - Technical Lead', 'Channel 4 (Exterior Ops)', false, 'Ingress & Box Office Lead', 31, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('7000.50.02', 'Credential Operations Coordinator', 'Front of House', 'Coordinator', 'Issues RFID wristbands, crew badges, vehicle passes, and enforces zone access permissions.', 'Program RFID credentials, audit zone permissions against roster, verify daily photo IDs.', '3+ years event accreditation and access credentialing administration.', 'Prolonged desk and check-in window operations.', 'Access Control System Administrator Certified', 'Tier 2 - Technical Lead', 'Channel 4 (Exterior Ops)', false, 'Master Credential & RFID Lead', 32, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('7000.51.01', 'Lead Event Paramedic / EMT', 'Guest Safety', 'Specialist', 'Manages on-site medical tent, triage protocols, minor injury care, and ambulance dispatch liaison.', 'Deliver immediate emergency life support, record patient triage logs, liaise with local EMS.', '5+ years emergency medical services and mass gathering event medicine.', 'Rapid response mobility, ability to carry medical trauma kits (40 lbs).', 'Licensed Paramedic / EMT-P, ACLS, PALS, CPR/AED', 'Tier 2 - Technical Lead', 'Channel 2 (Security)', false, 'On-Site Medical & Triage Lead', 33, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('8000.50.01', 'Head Beverage Director / Bar Manager', 'Beverage Service', 'Manager', 'Directs multi-station bar operations, draft beer lines, POS reconciliation, and liquor inventory.', 'Manage bar staff, track spirits depletion against cash/card receipts, oversee ice and garnish prep.', '6+ years high-volume festival or nightlife beverage management.', 'Continuous standing, lifting kegs (160 lbs with dolly) and liquor cases (45 lbs).', 'ServSafe Alcohol, TIPS Certified, FL Responsible Vendor', 'Tier 2 - Technical Lead', 'Channel 4 (Exterior Ops)', false, 'Master Bar & Beverage Lead', 34, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('8000.51.01', 'Executive Catering Captain', 'Catering Service', 'Manager', 'Supervises artist dressing room food service, crew meal buffets, dietary accommodations, and chafers.', 'Coordinate hot meal timing with show stage schedule, monitor buffet sanitation, manage servers.', '5+ years concert touring, festival, or corporate executive catering.', 'Continuous standing, walking between catering kitchens and green rooms, lifting 35 lbs.', 'ServSafe Food Manager Certified, Allergen Awareness Certified', 'Tier 2 - Technical Lead', 'Channel 4 (Exterior Ops)', false, 'Artist & Crew Catering Lead', 35, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('9000.50.01', 'Production Stage Manager', 'Stage Operations', 'Manager', 'Executes live run-of-show cues, stage deck turnover, and backline technical transitions.', 'Call stage cues, coordinate artist deck arrivals, enforce show schedule timing.', '6+ years calling major festival stages or theatrical productions.', 'Standing and moving backstage during full event duration.', 'Stage Management Association / OSHA 10', 'Tier 2 - Technical Lead', 'Channel 7 (Stage Ops)', false, 'Lead Deck Stage Manager', 9, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('9000.50.02', 'Audio Engineer - A1/FOH', 'Audio Systems', 'Lead Technician', 'Front-of-house engineer in charge of acoustic tuning, console mixing, and PA safety.', 'Mix FOH sound, optimize line array dispersion, oversee Dante audio networking.', '7+ years live concert audio engineering and system design.', 'Prolonged standing at mixing console, lifting 40 lbs.', 'Dante Level 3, SMAART Certification', 'Tier 2 - Technical Lead', 'Channel 8 (Audio)', false, 'Lead Audio Engineer FOH', 10, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('9000.50.03', 'Lighting Designer / LD', 'Lighting Systems', 'Lead Technician', 'Programs dynamic visual show cues, operates GrandMA console, and supervises lighting rig.', 'Program show files, oversee fixture focus and truss hanging, execute show lighting.', '5+ years moving light programming and concert lighting design.', 'Prolonged console operation, comfortable with heights.', 'GrandMA3 Programmer Certified, ETCP Preferred', 'Tier 2 - Technical Lead', 'Channel 9 (Lighting)', false, 'Lead Lighting Programmer', 11, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('9000.50.04', 'Video Director / V1', 'Video Systems', 'Lead Technician', 'Supervises LED wall processors, live video switching, media server playback, and camera feeds.', 'Manage video switching, synchronize media servers, calibrate LED panels.', '5+ years live video playback and LED video wall engineering.', 'Sedentary video control position with rapid deck response.', 'Barco Certified, Disguise D3 Workflow Certified', 'Tier 2 - Technical Lead', 'Channel 7 (Stage Ops)', false, 'Lead Video & Media Engineer', 12, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp),
  ('9000.52.01', 'Lead Network & Comms Engineer', 'Venue IT', 'Lead Technician', 'Deploys event core routers, managed switches, fiber optic trunks, high-density guest WiFi, and RF radios.', 'Configure VLAN segmentation, manage wireless access points, coordinate radio frequencies.', '6+ years temporary live event IT network infrastructure and RF coordination.', 'Able to lift 50 lbs, climb ladders, pull fiber runs through cable ramps.', 'Cisco CCNA / Network+, Shure RF Coordinator Certified', 'Tier 2 - Technical Lead', 'Channel 5 (Power & IT)', false, 'Core IT Network & RF Systems Lead', 36, 'Active', 'Julian Clarkson', '2026-09-15'::timestamp, '2026-09-15'::timestamp);
