insert into xpms.emergency_protocol_step (record_key, step_no, body) values
  ('EMG-001', 1, 'Identify fire source and immediately activate fire extinguishers.'),
  ('EMG-001', 2, 'Contact {fire}.'),
  ('EMG-001', 3, 'Clear and cordon off affected areas.'),
  ('EMG-001', 4, 'Shut off utilities (gas/electric).'),
  ('EMG-002', 1, 'Immediately cut power to stage equipment to prevent electrical fires.'),
  ('EMG-002', 2, 'Use extinguishers near stage if safe to do so.'),
  ('EMG-002', 3, 'Assist with evacuation of performers and crew.'),
  ('EMG-003', 1, 'Cease all operations.'),
  ('EMG-003', 2, 'Turn off cooking equipment.'),
  ('EMG-003', 3, 'Instruct staff to guide guests out safely.'),
  ('EMG-003', 4, 'Evacuate food areas and ensure propane tanks are turned off.'),
  ('EMG-004', 1, 'Direct guests to nearest exits.'),
  ('EMG-004', 2, 'Make PA announcements, if possible, to ensure orderly evacuation.'),
  ('EMG-004', 3, 'Assist guests with limited mobility or special needs.'),
  ('EMG-005', 1, 'Ensure artists and performers are safely escorted off stage/backstage.'),
  ('EMG-005', 2, 'Secure props and valuable equipment backstage to prevent further hazards.'),
  ('EMG-006', 1, 'Ensure all exits are accessible and open.'),
  ('EMG-006', 2, 'Assist in the evacuation of high-capacity zones, including VIP and public areas.'),
  ('EMG-006', 3, 'Provide basic first aid if needed.'),
  ('EMG-007', 1, 'Alert security teams and {lawEnforcement} immediately.'),
  ('EMG-007', 2, 'Isolate aggressors and provide crowd control to prevent escalation.'),
  ('EMG-007', 3, 'Assess if evacuation is necessary.'),
  ('EMG-008', 1, 'Turn off stage lighting and sound to avoid escalating tensions.'),
  ('EMG-008', 2, 'If necessary, pause performances and lock down stage access.'),
  ('EMG-009', 1, 'Cease alcohol sales.'),
  ('EMG-009', 2, 'Instruct staff to close registers and secure high-value items.'),
  ('EMG-009', 3, 'Secure equipment that can be used as weapons (e.g., knives, utensils).'),
  ('EMG-010', 1, 'Move guests away from the conflict area, using calm and non-confrontational communication.'),
  ('EMG-010', 2, 'Offer assistance to frightened or injured guests.'),
  ('EMG-011', 1, 'Backstage personnel to remain alert and report suspicious behavior.'),
  ('EMG-011', 2, 'Provide a safe room for artists if aggression occurs near performance area.'),
  ('EMG-012', 1, 'Assist security teams with crowd control and ensure that aggressors are contained away from general public.'),
  ('EMG-012', 2, 'Coordinate with medical teams if injuries occur.'),
  ('EMG-013', 1, 'Cut power to affected areas.'),
  ('EMG-013', 2, 'Inspect any visible structural damage (e.g., lighting rigs, barricades).'),
  ('EMG-013', 3, 'Work with electricians to restore power safely.'),
  ('EMG-014', 1, 'Secure all stage equipment and instruments to prevent further damage.'),
  ('EMG-014', 2, 'Pause performances and make an announcement explaining the situation.'),
  ('EMG-015', 1, 'Stop food prep to avoid injury.'),
  ('EMG-015', 2, 'If structural damage affects tents/kiosks, direct guests and staff to clear the area.'),
  ('EMG-016', 1, 'Calm guests and offer clear instructions to avoid panic.'),
  ('EMG-016', 2, 'Guide guests to alternate exits if structural damage affects egress routes.'),
  ('EMG-017', 1, 'Ensure that artists are safe backstage and equipment is not at risk of being damaged.'),
  ('EMG-017', 2, 'Organize personnel to inspect and report any damage in restricted areas.'),
  ('EMG-018', 1, 'Guide guests to safety and inform them of alternative actions (delays or cancellations).'),
  ('EMG-018', 2, 'Assist in directing crowds away from dangerous areas.'),
  ('EMG-019', 1, 'Increase security patrols in sensitive areas (e.g., entrances, high-traffic areas).'),
  ('EMG-019', 2, 'Report all thefts to {lawEnforcement}.'),
  ('EMG-019', 3, 'Conduct bag checks at exits, if needed.'),
  ('EMG-020', 1, 'Secure all stage equipment, especially high-value instruments or electronics.'),
  ('EMG-020', 2, 'Coordinate with security to monitor artist equipment and dressing rooms.'),
  ('EMG-021', 1, 'Lock down cash registers and remove high-value items from view.'),
  ('EMG-021', 2, 'Report suspicious behavior to security.'),
  ('EMG-021', 3, 'Implement a strict cash-handling procedure.'),
  ('EMG-022', 1, 'Assist guests in filing lost or stolen property reports.'),
  ('EMG-022', 2, 'Use public announcements to inform guests of the incident, if needed.'),
  ('EMG-023', 1, 'Secure personal and valuable equipment for artists and performers.'),
  ('EMG-023', 2, 'Monitor access to VIP areas to prevent unauthorized entry.'),
  ('EMG-024', 1, 'Assist security in ensuring all exits are covered.'),
  ('EMG-024', 2, 'Implement crowd control to prevent thefts during egress.'),
  ('EMG-024', 3, 'Handle guest complaints regarding lost items.'),
  ('EMG-025', 1, 'Immediately call {ems} or direct on-site medical personnel.'),
  ('EMG-025', 2, 'Clear space for medical teams to access the affected individual.'),
  ('EMG-025', 3, 'Use first aid kits if necessary.'),
  ('EMG-026', 1, 'Pause performance to direct attention to the medical emergency.'),
  ('EMG-026', 2, 'Keep communication channels open to ensure paramedics can access the stage area.'),
  ('EMG-027', 1, 'Offer water or basic care (if applicable).'),
  ('EMG-027', 2, 'Instruct staff to guide {ems} to the food area if needed.'),
  ('EMG-028', 1, 'Alert guests to make way for medical personnel.'),
  ('EMG-028', 2, 'Provide support to affected individuals until {ems} arrives.'),
  ('EMG-029', 1, 'Ensure performers and crew are safe and are not obstructing medical responders.'),
  ('EMG-029', 2, 'Provide medics with direct access to the backstage area if needed.'),
  ('EMG-030', 1, 'Coordinate with medical teams to facilitate access to emergency locations.'),
  ('EMG-030', 2, 'Keep guests informed about delays or disruptions due to the emergency.'),
  ('EMG-031', 1, 'Activate emergency protocol and increase security presence.'),
  ('EMG-031', 2, 'Prepare evacuation routes and ensure exits are clear.'),
  ('EMG-031', 3, 'Work with {lawEnforcement} for guidance and assistance.'),
  ('EMG-032', 1, 'Stop the performance to prevent escalation.'),
  ('EMG-032', 2, 'Secure stage and assist in evacuating performers and staff to a safe area.'),
  ('EMG-033', 1, 'Lock down all kiosks, close food prep areas.'),
  ('EMG-033', 2, 'Move staff to safe areas and prepare for evacuation.'),
  ('EMG-034', 1, 'Calm guests and direct them to safety if evacuation becomes necessary.'),
  ('EMG-034', 2, 'Provide real-time updates using PA system or megaphones.'),
  ('EMG-035', 1, 'Ensure artists are safely escorted off-site if necessary.'),
  ('EMG-035', 2, 'Secure dressing rooms and valuables.'),
  ('EMG-036', 1, 'Assist in managing crowds to prevent disorder.'),
  ('EMG-036', 2, 'Ensure clear communication with guests, informing them about actions being taken for their safety.'),
  ('EMG-037', 1, 'Provide requested permits, licenses, and compliance documentation to the agency.'),
  ('EMG-037', 2, 'Ensure all areas meet safety standards (fire exits, lighting, structural integrity).'),
  ('EMG-038', 1, 'Pause the performance if requested by officials.'),
  ('EMG-038', 2, 'Ensure all stage operations are compliant with safety regulations (sound levels, rigging).'),
  ('EMG-039', 1, 'Provide food handling permits, alcohol licenses, and health inspection certificates upon request.'),
  ('EMG-040', 1, 'Inform guests of any temporary delays due to inspections.'),
  ('EMG-040', 2, 'Provide support to guests and reassure them that the event is in compliance with safety protocols.'),
  ('EMG-041', 1, 'Ensure back-of-house areas meet safety regulations and provide access to officials for inspections.'),
  ('EMG-041', 2, 'Maintain communication with event management.'),
  ('EMG-042', 1, 'Assist in ensuring that front-of-house operations meet health, safety, and accessibility regulations.'),
  ('EMG-042', 2, 'Provide compliance documentation to authorities if required.'),
  ('EMG-043', 1, 'Immediately contact {lawEnforcement}, {fire}, and {federal}.'),
  ('EMG-043', 2, 'Activate emergency evacuation protocols.'),
  ('EMG-043', 3, 'Secure all entrances and exits.'),
  ('EMG-044', 1, 'Cut stage power and lighting to avoid panic.'),
  ('EMG-044', 2, 'Assist security in evacuating artists and crew to secure areas.'),
  ('EMG-045', 1, 'Cease all operations and secure food stands.'),
  ('EMG-045', 2, 'Ensure that all dangerous equipment (e.g., propane tanks) is turned off and locked down.'),
  ('EMG-046', 1, 'Announce evacuation instructions clearly and calmly.'),
  ('EMG-046', 2, 'Assist guests with disabilities or mobility challenges in evacuating.'),
  ('EMG-047', 1, 'Secure VIP and performer areas to prevent unauthorized access.'),
  ('EMG-047', 2, 'Escort artists and staff to safety through pre-established emergency routes.'),
  ('EMG-048', 1, 'Ensure all exit points are secure but accessible for a controlled evacuation.'),
  ('EMG-048', 2, 'Provide first aid support if necessary.'),
  ('EMG-049', 1, 'Report substance use to security and law enforcement.'),
  ('EMG-049', 2, 'Assist in monitoring suspicious activity and help contain the situation.'),
  ('EMG-050', 1, 'Halt the performance and coordinate with security if illicit substances are suspected backstage.'),
  ('EMG-050', 2, 'Maintain communication with artists and crew regarding safety.'),
  ('EMG-051', 1, 'Cease alcohol sales and report any incidents of illegal substance use near food stations.'),
  ('EMG-051', 2, 'Monitor guests for signs of intoxication and report to security.'),
  ('EMG-052', 1, 'Report any suspicious activity to security.'),
  ('EMG-052', 2, 'Assist guests in reporting concerns related to substance use or safety.'),
  ('EMG-053', 1, 'Ensure backstage areas are free of illegal substances and report any issues to management and law enforcement.'),
  ('EMG-054', 1, 'Alert security and provide support for guests affected by substance use.'),
  ('EMG-054', 2, 'Ensure that proper protocols for dealing with intoxicated guests are followed.'),
  ('EMG-055', 1, 'Contact talent management immediately to locate missing talent.'),
  ('EMG-055', 2, 'Coordinate with other departments to adjust schedules as necessary.'),
  ('EMG-056', 1, 'Delay performance and provide alternate acts or entertainment, if possible.'),
  ('EMG-056', 2, 'Ensure that backup performers are ready to take the stage if needed.'),
  ('EMG-057', 1, 'Adjust food and beverage schedules to account for possible delays or cancellations.'),
  ('EMG-057', 2, 'Inform staff of changes in the performance schedule.'),
  ('EMG-058', 1, 'Inform guests of any delays or changes in performances through the PA system.'),
  ('EMG-058', 2, 'Provide alternative forms of entertainment or services, if possible.'),
  ('EMG-059', 1, 'Work with talent agents to locate the missing artist.'),
  ('EMG-059', 2, 'Prepare alternate accommodations for talent if transportation issues are causing delays.'),
  ('EMG-060', 1, 'Ensure all front-of-house staff are informed of changes.'),
  ('EMG-060', 2, 'Coordinate guest services to handle inquiries and possible complaints about the missing act.'),
  ('EMG-061', 1, 'Immediately notify {lawEnforcement} and security personnel.'),
  ('EMG-061', 2, 'Lock down all entrances and exits.'),
  ('EMG-061', 3, 'Instruct staff to move guests to pre-designated secure areas or evacuate.'),
  ('EMG-062', 1, 'Cut stage lights and sound to reduce visibility and prevent panic.'),
  ('EMG-062', 2, 'Ensure performers are evacuated to safe areas backstage.'),
  ('EMG-063', 1, 'Cease operations and direct staff to secure food areas.'),
  ('EMG-063', 2, 'Lock down all exits from food tents and kiosks.'),
  ('EMG-064', 1, 'Calmly guide guests to secure areas or nearest exits as directed by security.'),
  ('EMG-064', 2, 'Help guests find shelter in place if an evacuation is not immediately possible.'),
  ('EMG-065', 1, 'Secure VIP and backstage areas.'),
  ('EMG-065', 2, 'Help performers evacuate through secure routes or lock down in safe areas.'),
  ('EMG-066', 1, 'Direct guests toward exits and assist law enforcement with crowd control.'),
  ('EMG-066', 2, 'Provide medical support for any injuries.'),
  ('EMG-067', 1, 'Notify {lawEnforcement} and {bombSquad} immediately.'),
  ('EMG-067', 2, 'Clear and evacuate areas as directed by law enforcement.'),
  ('EMG-067', 3, 'Avoid using radios or cell phones in case of detonation risk.'),
  ('EMG-068', 1, 'Secure all stage equipment and evacuate performers and crew to safe areas.'),
  ('EMG-068', 2, 'Work with authorities to ensure proper procedures are followed for bomb threat investigation.'),
  ('EMG-069', 1, 'Cease operations and evacuate staff to designated safety areas.'),
  ('EMG-069', 2, 'Secure propane tanks and any flammable materials.'),
  ('EMG-070', 1, 'Calmly announce evacuation procedures and direct guests to exits without causing panic.'),
  ('EMG-070', 2, 'Assist guests with disabilities or limited mobility.'),
  ('EMG-071', 1, 'Evacuate backstage personnel to safe areas.'),
  ('EMG-071', 2, 'Ensure that performers are kept in secure locations until further instruction from law enforcement.'),
  ('EMG-072', 1, 'Ensure all exits are accessible for rapid evacuation.'),
  ('EMG-072', 2, 'Assist law enforcement with crowd control and provide medical support as needed.'),
  ('EMG-073', 1, 'Notify security and lock down vulnerable access points.'),
  ('EMG-073', 2, 'Assist security in managing crowds and preventing unauthorized individuals from entering secure areas.'),
  ('EMG-074', 1, 'Lock down stage access and evacuate performers if necessary.'),
  ('EMG-074', 2, 'Secure valuable stage equipment.'),
  ('EMG-075', 1, 'Shut down food operations and secure high-value items.'),
  ('EMG-075', 2, 'Assist security in monitoring access points to prevent unauthorized entry.'),
  ('EMG-076', 1, 'Reassure guests and prevent panic.'),
  ('EMG-076', 2, 'Move guests away from the area of the breach to safer locations.'),
  ('EMG-077', 1, 'Secure backstage areas, ensuring unauthorized personnel do not access dressing rooms or restricted zones.'),
  ('EMG-078', 1, 'Secure all exits and entry points to prevent unauthorized access.'),
  ('EMG-078', 2, 'Coordinate with security and local law enforcement to handle breach.'),
  ('EMG-079', 1, 'Alert security and event management.'),
  ('EMG-079', 2, 'Assist with immediate searches using pre-assigned personnel.'),
  ('EMG-079', 3, 'Make announcements over PA system or use digital alerts.'),
  ('EMG-080', 1, 'Suspend performance temporarily if necessary to coordinate searches.'),
  ('EMG-080', 2, 'Ensure all stage staff are briefed on the missing person situation.'),
  ('EMG-081', 1, 'Instruct food and beverage staff to monitor exits and inform security if the missing person is seen.'),
  ('EMG-082', 1, 'Assist in locating missing individuals by directing security or offering descriptions to staff.'),
  ('EMG-082', 2, 'Guide guardians to a secure meeting point.'),
  ('EMG-083', 1, 'Help secure backstage areas and prevent unauthorized personnel from entering.'),
  ('EMG-083', 2, 'Assist in search efforts by monitoring restricted areas.'),
  ('EMG-084', 1, 'Coordinate with law enforcement and search teams to monitor exits.'),
  ('EMG-084', 2, 'Assist with family reunification processes.');
