insert into xpms.std_sop (source_row, sop_id, title, operational_domain, revision, organization, project, department, category, sub_category, accountable_role_code, required_ppe_compliance_tag, prerequisites_and_hazards, procedure_step_1, procedure_step_2, procedure_step_3, procedure_step_4, reference_doc_id, status, flag, notes, created_by, created_at, updated_at) values
  (2, 'SOP-001', 'Overhead Rigging & Motor Inspection Protocol', 'Structural & Rigging Safety', 'v2.0', null, null, '5000 Production', '5000.05.02', 'Overhead Rigging', '5000.51.02', 'TAG-002 OSHA · TAG-022 ETCP · Hard Hat, ANSI Steel-Toe Boots, High-Vis Vest, Fall Arrest Harness', 'Verify structural stamped load capacity (DOC-004), verify clear drop zone below trusses, and lock out ground personnel.', 'Pre-Rig Inspection: Inspect all 1-ton CM lodestar chain hoists, steel cables, shackles, and Spansets for wear, deformation, or certification expiration.', 'Bridle & Point Hanging: Attach engineered beam clamps to approved building structural nodes per stamped plot; rig motor hoist cables with safety secondary.', 'Truss Assembly & Dead-Hang Proof: Pin 20.5-inch box truss sections; run cable looms; perform dead-lift test bump to 3 feet; verify shackle mousing and weight distribution.', 'Trim Height Lockout: Hoist rig to final trim elevation (22 ft); engage secondary safety safeties/steel chokers; tag out controller box at FOH.', 'DOC-004', 'Active', false, 'OSHA & ETCP compliant overhead rigging inspection procedure.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (3, 'SOP-002', 'Temporary Event Power Distribution & Generator Energization', 'High-Voltage Electrical Safety', 'v1.2', null, null, '5000 Production', '5000.06.01', 'Electrical Distribution', '5000.50.02', 'TAG-002 OSHA · TAG-041 NEC · NFPA 70E Arc-Flash Face Shield, Class 0 Insulated Gloves, Safety Glasses', 'Permit EL-2026-04421 on file (DOC-003); 400A diesel generator grounded to 25 ohms or less; lockout/tagout in effect.', 'Grounding & Feeder Lay: Drive copper grounding rod; test soil resistance with earth ground meter; lay 4/0 AWG feeder runs in heavy-duty yellow jacket cable ramps.', 'Cam-Lock Connection Sequence: Connect Ground (Green), Neutral (White), Phase C (Blue), Phase B (Red), Phase A (Black) in strict NEC sequence.', 'Energization & Phase Rotation: Power generator to 60 Hz idle; verify phase voltage (120V/208V 3-phase) and rotation meter before closing main distribution breaker.', 'Sub-Distro Branch Load Balancing: Energize audio, lighting, and video distribution boxes sequentially; monitor balanced amp draw across all 3 legs (max 80% derate).', 'DOC-003', 'Active', false, 'NEC & NFPA 70E temporary power tie-in and generator energization protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (4, 'SOP-003', 'Concert Line Array Tuning & Perimeter SPL Curfew Enforcement', 'Acoustic Systems & Municipal Compliance', 'v2.0', null, null, '5000 Production', '5000.01.02', 'Audio Engineering', '9000.50.02', 'TAG-002 OSHA · Hearing Protection (Custom Molded / High-Fidelity Earplugs)', 'EASE plot alignment confirmed (DOC-005); SMAART acoustic measurement rig calibrated; stage clear of non-audio crew.', 'Pink Noise Line Check & Phase Verification: Sweep pink noise through individual speaker elements (tops, downfills, subs); confirm polarity and phase coherence in SMAART.', 'Cardioid Sub Optimization: Align delay and phase cancellation on rear-facing sub elements to create 18dB rear rejection toward Biscayne property boundary.', 'System EQ & Target Curve Voicing: Apply room curve filtering for vocal clarity and dynamic range; tune FOH mix position to target 98 dBA Leq (15 min).', 'Perimeter Curfew Logging: Deploy remote Type 2 sound level meter at property edge; continuously record calibrated SPL to verify <78 dBA compliance through midnight.', 'DOC-005', 'Active', false, 'Acoustic line array tuning and Biscayne perimeter SPL curfew compliance.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (5, 'SOP-004', 'Severe Weather Monitoring & Temporary Structure Evacuation', 'Life Safety & Weather Trigger Management', 'v1.5', null, null, '6000 Operations', '6000.05.01', 'Severe Weather & Egress', '6000.50.02', 'TAG-002 OSHA · TAG-019 NFPA · Weatherproof Tactical Hi-Vis Outerwear, Flashlight, Two-Way Radio (Channel 1)', 'On-site calibrated anemometer active; live radar weather monitoring feed connected; Emergency Action Plan active (DOC-008).', 'Advisory State (25 MPH Gusts / Lightning <15 Miles): Notify Executive Producer and Department Heads via Radio Ch 1; inspect tent ballasts and loose signage.', 'Restricted State (35 MPH Gusts / Lightning <8 Miles): Pause high-altitude staging/aerial lifts; lower flying LED walls to safety deck; pause patio dining service.', 'Evacuation Trigger (45 MPH Gusts / Lightning <5 Miles): Trigger mass notification; illuminate emergency work lights; activate orderly egress toward indoor sanctuary (LOC-01).', 'Post-Storm All-Clear & Inspection: Conduct structural engineering inspection of outdoor canopies, rigging points, and electrical lines before re-admitting guests.', 'DOC-008', 'Active', false, 'Severe weather action levels and temporary structure evacuation protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (6, 'SOP-005', 'Assembly Occupancy Ingress & Egress Door Control', 'Crowd Management & Fire Code Compliance', 'v1.0', null, null, '6000 Operations', '6000.50.01', 'House Management', '6000.50.01', 'TAG-002 OSHA · TAG-006 ADA · Certified Crowd Manager Badge, Hi-Vis Identification Lanyard', 'Assembly permit BD-2026-08914 approved (DOC-002); master egress widths verified (DOC-001); minimum 8 crowd managers on post.', 'Pre-Ingress Life Safety Walk: Walk all exit corridors, panic hardware, emergency illuminated exit signs, and fire extinguisher stations; verify zero pathway obstructions.', 'Queue Line Stanchion Configuration: Establish ADA-compliant arrival switchbacks (36-inch clear path); position RFID scanners; open check-in gates at T-00:30 (18:00).', 'Capacity Flow Tracking: Monitor real-time headcount dashboard; maintain headcount under 350 occupant maximum; enforce 1-in-1-out policy if capacity reached.', 'Egress Call & Doors Clearance: At event conclusion (23:00), prop all double exit doors fully open; guide patron flow toward rideshare dispatch hub on 76th St.', 'DOC-002', 'Active', false, 'Assembly occupancy door control and crowd manager egress coordination.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (7, 'SOP-006', 'Live Performance Show Calling & Cue Execution Sequence', 'Stage Management & Live Production Control', 'v3.1', null, null, '9000 Technology', '9000.50.01', 'Show Calling', '9000.50.01', 'TAG-002 OSHA · Clear-Com Headset, Production Flashlight with Red Filter', 'Run of Show cue list locked; SMPTE timecode sync verified with playback and lighting consoles; talent green room escorts standby.', 'Comms Line Check (T-00:15): Establish multi-channel comms check with Audio (Ch A), Lighting (Ch B), Video (Ch C), and Stage Deck (Ch D); verify cue lights green.', 'Standby Call Cadence: Issue standard verbal standbys precisely 30 seconds prior to cue trigger: \"Standby Audio Cue 05, Standby Lighting Look 05, Standby Video Blade 05\".', 'Cue Execution Call: Call crisp execution trigger on downbeat or timecode mark: \"Audio, Lights, Video... GO.\" Confirm acknowledge from all discipline operators.', 'Hold & Abort Protocol: In the event of deck hazard, performer distress, or safety breach, immediately call \"HOLD, HOLD, HOLD\" on all channels and take stage to safe wash.', 'DOC-007', 'Active', false, 'Live performance cue execution sequence and emergency hold protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (8, 'SOP-007', 'Real-Time Media Ingest, Checksum Verification & Social Reel Delivery', 'Digital Asset Management & PR Workflow', 'v1.0', null, null, '3000 Marketing', '3000.50.02', 'Media Production', '3000.50.02', 'TAG-026 PCI · Anti-Static Handling Wrist Strap, Media Hard Drive Vault Bags', '10GbE NAS network connected; cleared artist music sync rights on file; Casa Spotify Brand Toolkit active (DOC-006).', 'CFexpress / SD Card Offload: Ingest raw 4K camera cards via ShotPut Pro; compute MD5/xxHash checksum verification to primary NVMe RAID storage.', 'Secondary Cloud Backup: Trigger automated parallel upload to Google Drive archive directory and off-site cloud bucket with version tagging.', 'Editorial & Color Grading: Conform footage in Premiere Pro / DaVinci Resolve using Casa Spotify Wynwood LUT; apply official Spotify logo bugs and artist titles.', 'PR & Social Master Handoff: Export 9x16 vertical reels (H.264/ProRes) within 90 minutes of set completion; push assets to PR distribution team with cleared usage metadata.', 'DOC-006', 'Active', false, 'Real-time media card offload, checksum verification, and PR reel delivery.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (9, 'SOP-008', 'Post-Show Strike Sequence & Venue Space Restoration', 'Load-Out Logistics & Space Handover', 'v2.0', null, null, '5000 Production', '5000.51.01', 'Stage & Rig Strike', '5000.51.01', 'TAG-002 OSHA · Steel-Toe Boots, Heavy Leather Rigging Gloves, High-Vis Vest, Hard Hat', 'Audience 100% egressed; venue power isolated; truck staging bay active in Marshalling Yard; Work Order WO-002 active.', 'Backline & Microphones Strike: Disconnect instrument mics, pack artist backline into ATA flight cases; secure high-value wireless gear into locked Pelican cases.', 'LED Wall & Lighting Truss Drop: Lower overhead trusses to 4 ft service height; de-cable pixel tape and DMX looms; pack LED video tiles into custom road cases.', 'Motor De-Rig & Cable Pull: Slack chain hoists; derig beam clamps; coil 4/0 feeder cables into rolltainers; strike temporary distro boxes to staging dock.', 'Sanitation Sweep & Venue Handover: Conduct sweeping and debris removal across sanctuary floor and El Patio; conduct joint walk with venue manager for damage sign-off.', 'DOC-001', 'Active', false, 'Post-show stage strike, equipment packing, and venue space restoration.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (10, 'SOP-009', 'Temporary Demountable Structures (TDS) Ballast & Wind Bracing Protocol', 'Temporary Structures & Wind Engineering', 'v1.4', null, null, '4000 Environment', '4000.08.02', 'Tents & Temporary Structures', '4000.50.01', 'TAG-002 OSHA · TAG-008 TENT_PERMIT · TAG-036 STRUCT_ENG · Hard Hat, Steel-Toe Boots, High-Vis Vest', 'Stamped engineering ballast calculation on file (DOC-009); calibrated water meter/crane scale for weight verification; anemometer active.', 'Pre-Erection Footing Inspection: Verify subgrade compaction, asphalt integrity, and laser-level baseplate pads; position pre-cast concrete ballast blocks per structural plot.', 'Frame Truss Pinning & Squaring: Assemble structural aluminum box arches on ground; verify diagonal squareness within 0.25 in; insert all structural pins and safety R-clips.', 'Ballast Rigging & Guying: Connect high-tensile ratchet straps and 3/8-in wire rope guying to concrete weights; tension each guy wire to engineered load specification.', 'Membrane Tensioning & Flame Cert Log: Pull fire-retardant vinyl canopies through keder rails; ratchet tension to prevent wind pocketing; post NFPA 701 flame cert tag at mast.', 'DOC-009', 'Active', false, 'ANSI ES1.7 & Florida Building Code temporary structure ballast and guy wire protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (11, 'SOP-010', 'Stage Pyrotechnics, Flame Effects & Cold Spark Safety Sequence', 'Pyrotechnics & Atmospheric Effects Safety', 'v1.0', null, null, '5000 Production', '5000.07.01', 'Atmospheric Effects', '5000.52.01', 'TAG-002 OSHA · TAG-019 NFPA · TAG-038 PYRO_LICENSE · Nomex Flame-Resistant Jacket, Safety Glasses, 2A-10BC Extinguisher', 'City of Miami Fire-Rescue permit active (DOC-010); designated 15-foot separation safety zone established; Miami Fire watch on duty.', 'Hardware & Fuel Integrity Inspection: Inspect LP-gas hoses, solenoid valves, and titanium cold-spark granules; verify pressure regulators and emergency deadman switches.', 'Perimeter Barrier & Line-of-Sight Lock: Establish physical stanchions 15 ft from discharge nozzles; verify clear overhead clearance to trussing (>25 ft) and drapery.', 'Arming Sequence & Pyro Controller Link: Connect digital firing controller via isolated dry-contact DMX line; verify continuity; arm system only on stage manager verbal standby.', 'Post-Fire Safe Depressurization & Canister Lock: Disarm firing console immediately post-cue; vent residual gas lines; vacuum titanium dust; lock canisters in pyro vault.', 'DOC-010', 'Active', false, 'NFPA 160 & NFPA 1126 stage flame effects and cold spark firing procedure.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (12, 'SOP-011', 'Class 3B/4 Audience-Scanned Laser Alignment & Termination Safety', 'Optical Radiation & Laser Safety', 'v1.0', null, null, '5000 Production', '5000.07.01', 'Atmospheric Effects', '9000.50.03', 'TAG-002 OSHA · TAG-018 ANSI · Laser Safety Eyewear (OD 7+ @ 520nm/450nm/638nm)', 'FDA CDRH variance valid (DOC-011); certified Laser Safety Officer (LSO) on site; hard mechanical beam stops anchored.', 'Physical Rigging & E-Stop Verification: Mount RGB projector to rigid truss with secondary safety cable; wire hardwired emergency mushroom e-stop at FOH control position.', 'Scan-Fail Circuit & Masking Calibration: Calibrate hardware scan-fail interlock boards; configure geometric software masking zones to prevent exposure below 10 ft from floor.', 'Low-Power Beam Alignment & Termination Proof: Power up laser in 1% alignment mode; verify all bounce mirrors and strike non-reflective fire-rated beam dumps.', 'Full-Power Exposure Metering & LSO Sign-Off: Measure Maximum Permissible Exposure (MPE) at closest patron boundary using calibrated laser power meter; record LSO log.', 'DOC-011', 'Active', false, 'ANSI Z136.1 & FDA CDRH 21 CFR 1040.10 outdoor entertainment laser safety protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (13, 'SOP-012', 'Environmental Noise Monitoring & Wynwood Perimeter SPL Curfew Enforcement', 'Acoustic Systems & Municipal Compliance', 'v2.0', null, null, '5000 Production', '5000.01.02', 'Audio Engineering', '9000.50.02', 'TAG-002 OSHA · Type 1/2 Calibrated Sound Level Meter, High-Vis Vest, Two-Way Radio', 'Municipal sound variance on file (DOC-012); acoustical calibrator (94 dB / 114 dB) checked; remote logging telemetry online.', 'Field Calibrator Verification: Mount microphone on remote perimeter meter; apply 94.0 dB acoustical calibrator; log reference drift within +/-0.3 dB before event start.', 'FOH Leq Ceiling Enforcement: Set software limiter threshold at FOH console to cap continuous mix volume at 98 dBA Leq (15-min rolling window).', 'Boundary Telemetry Real-Time Tracking: Continuously monitor property boundary meters along Biscayne Blvd; alert FOH A1 if 5-min Leq approaches 76 dBA.', 'Midnight Curfew Step-Down Execution: At 23:59 EDT, execute programmed console master mute on all outdoor PA elements; file continuous SPL audit log to city compliance portal.', 'DOC-012', 'Active', false, 'City of Miami Chapter 36 Noise Ordinance and perimeter SPL monitoring procedure.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (14, 'SOP-013', 'Temporary Commercial Kitchen Sanitation & Food Safety Inspection', 'Culinary Health & Sanitary Compliance', 'v1.0', null, null, '8000 Hospitality', '8000.01.01', 'Catering & Culinary', '8000.51.01', 'TAG-002 OSHA · TAG-010 HEALTH_DEPT · TAG-011 SERVSAFE · Non-Slip Shoes, Food-Grade Nitrile Gloves, Beard Net / Hair Net', 'Florida DBPR food service license posted (DOC-013); potable hot water station operational (min 100 deg F); digital stem thermometers calibrated in ice bath.', 'Cold-Chain Receiving & Temperature Verification: Probe all incoming TCS foods (poultry, beef, seafood, dairy); verify internal temp <41 deg F; reject out-of-spec shipments.', 'Handwashing & 3-Compartment Sink Setup: Establish dedicated handwash station with warm water, soap, single-use paper towels; set wash/rinse/sanitize (200 ppm Quat) sink bays.', 'Holding Temperature & Cross-Contamination Control: Monitor hot holding units (>135 deg F) and refrigerated prep tables (<41 deg F) every 2 hours; enforce allergen color-coding.', 'Shift Waste Disposal & Sanitizing Break-Down: Discard holding foods at 4-hour mark; sanitize stainless steel prep surfaces with quaternary solution; seal trash cans.', 'DOC-013', 'Active', false, 'Florida Administrative Code 61C-4 & FDA Food Code temporary food establishment protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (15, 'SOP-014', 'Alcoholic Beverage Dispensing, Age Verification & Intoxication Interception', 'Alcohol Governance & Hospitality Compliance', 'v1.1', null, null, '8000 Hospitality', '8000.02.01', 'Bar & Beverage', '8000.50.01', 'TAG-012 TIPS · TAG-013 LIQUOR_LICENSE · Certified TIPS/ServSafe Alcohol Badge, Bar Apron', 'Florida DBPR ABT permit posted (DOC-014); electronic ID barcode scanners active at all bar stations; security liaison assigned to bar perimeter.', '100% ID Scanning & Wristband Verification: Inspect physical photo ID for all patrons requesting alcohol; verify age 21+ via optical scanner; confirm intact 21+ wristband.', 'Standard Pour Volume & Recipe Control: Utilize measured jiggers for all spirit pours (1.5 oz spirit maximum per drink); enforce strict 2-drink maximum per transaction.', 'Behavioral Intoxication Assessment: Monitor guests for slurred speech, motor instability, or combative behavior; refuse service tactfully using non-confrontational phrasing.', 'Cut-Off Protocol & Security Dispatch: In event of refused service, immediately notify Bar Manager and dispatch roving Security Officer to offer hydration and rideshare escort.', 'DOC-014', 'Active', false, 'Florida Statute 561 & 562 beverage law compliance and responsible vendor procedure.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (16, 'SOP-015', 'Mass-Gathering Emergency Medical Dispatch, Triage & Heat Illness Protocol', 'Emergency Medical Services & Life Safety', 'v2.1', null, null, '6000 Operations', '6000.05.02', 'Medical & EMS', '7000.51.01', 'TAG-002 OSHA · TAG-028 HIPAA · Nitrile Exam Gloves, N95 Mask, High-Vis Medical Vest, Two-Way Radio (Channel 2)', 'Miami-Dade Fire Rescue medical plan active (DOC-015); on-site air-conditioned medical tent established; dedicated ALS ambulance parked in dock bay.', 'Triage Bay Readiness & Equipment Check: Perform daily operational bump check on Zoll AED, oxygen cylinders, suction units, and trauma jump kits; confirm cold IV saline stores.', 'Roving Medic Rapid-Response Cadence: Deploy pairs of EMTs across Main Stage and El Patio; maintain 3-minute maximum response radius to any distress call on Radio Ch 2.', 'Heat Illness & Substance Harm Reduction: Triage symptomatic patrons; initiate rapid evaporative cooling, electrolyte fluid replacement, and vital signs monitoring every 10 min.', '911 Escalation & Secure Transport Handoff: For red-tier critical patients, coordinate seamless patient transfer to Miami-Dade Fire Rescue ALS transport unit via Gate 3 access lane.', 'DOC-015', 'Active', false, 'Florida EMS Chapter 401 & NFPA 3000 mass gathering emergency medical protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (17, 'SOP-016', 'Physical Security Perimeter Access, Metal Detection & Bag Inspection', 'Security Operations & Threat Mitigation', 'v2.0', null, null, '6000 Operations', '6000.04.01', 'Security & Access Control', '6000.52.01', 'TAG-002 OSHA · TAG-021 BG_CHECK · Uniformed Security Officer Attire, Flashlight, Two-Way Radio (Channel 1)', 'City of Miami approved security overlay on file (DOC-016); walk-through magnetometers calibrated; prohibited items amnesty bins staged outside entry switchbacks.', 'Entry Lane Divestment Screening: Instruct arriving patrons to divest metallic items into inspection trays; visually inspect clear bags (12x6x12 in max) with wooden inspection dowel.', 'Walk-Through Magnetometer Processing: Guide patrons through magnetometer at standard cadence; conduct secondary screening with handheld wand if zone alert triggers.', 'Prohibited Item Confiscation & Chain of Custody: Safely confiscate contraband, weapons, or unauthorized recording rigs; deposit into locked evidence locker; log owner info.', 'Threat Interception & Law Enforcement Handover: If illegal firearms or hostile behavior detected, immediately detain subject, initiate ICS emergency call, and hand over to on-site MPD.', 'DOC-016', 'Active', false, 'DHS Active Shooter & Florida Class D security guard screening standards.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (18, 'SOP-017', 'Public Right-of-Way Traffic Control & Marshalling Yard Truck Staging', 'Traffic Engineering & Logistics Coordination', 'v1.3', null, null, '6000 Operations', '6000.02.07', 'Trucks & Transport', '6000.51.02', 'TAG-002 OSHA · TAG-016 DOT · ANSI Class 3 High-Vis Vest, Steel-Toe Boots, Hard Hat, Traffic Wand, Radio (Channel 3)', 'City of Miami / FDOT MOT permit active (DOC-017); certified traffic flaggers positioned; Type II traffic cones and electronic arrow board deployed along 76th St.', 'Street Closure Signage & Arrow Board Activation: Deploy advance warning signs (''ROAD WORK AHEAD'', ''LANE CLOSED'') per FDOT index; power electronic directional arrow board.', 'Carrier Dispatch & Marshalling Check-In: Intercept arriving 53-ft tractor-trailers at holding yard; verify carrier Bill of Lading (BOL), driver phone, and assigned dock appointment.', 'Dock Call & Reversing Spotter Escort: Guide truck from holding bay into loading dock; assign 2 ground spotters with safety whistles to clear pedestrian sidewalk traffic.', 'Wheels Chocking & Loading Ramp Deployment: Place heavy-duty rubber wheel chocks under rear trailer tandem; engage dock leveler lip before authorizing forklift load-in.', 'DOC-017', 'Active', false, 'FDOT Standard Plans Index 102 & MUTCD Part 6 traffic control and freight staging procedure.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (19, 'SOP-018', 'Commercial Drone Aerial Video Capture & Airspace Safety Protocol', 'Aviation Safety & UAS Operations', 'v1.0', null, null, '5000 Production', '5000.08.01', 'Cameras & Capture', '3000.50.02', 'TAG-003 FAA · TAG-023 FAA_PART107 · High-Vis Flight Crew Vest, Safety Glasses, Two-Way Radio', 'FAA Part 107 waiver on file (DOC-018); LAANC airspace authorization verified; dedicated Visual Observer (VO) positioned on sanctuary roof deck.', 'Pre-Flight Airspace & Telemetry Inspection: Conduct pre-flight drone inspection (rotors, gimbal, obstacle sensors); confirm GPS lock (>16 satellites); set Return-to-Home altitude to 150 ft.', 'Visual Observer Comms & Geo-Fence Setup: Establish continuous voice comms between Pilot in Command (PIC) and VO; lock geofence boundaries to prevent flight over unshielded crowds.', 'In-Flight Mission Execution & Battery Thresholds: Execute programmed sweeping cinematic passes; initiate mandatory return and landing sequence when battery telemetry reaches 25%.', 'Post-Flight Media Offload & Flight Logging: Power down aircraft; offload flight logs and micro-SD footage cards; log total flight hours and airspace compliance into ops portal.', 'DOC-018', 'Active', false, 'FAA Part 107 federal regulations and commercial UAS safe flight operation protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (20, 'SOP-019', 'ADA Accessibility, Companion Seating & Barrier-Free Path Management', 'Universal Accessibility & Guest Services', 'v2.0', null, null, '7000 Experience', '7000.01.01', 'Guest Experience & Journey', '7000.50.01', 'TAG-006 ADA · Front-of-House Credential Badge, Digital Ingress Scanner', 'Master ADA survey on file (DOC-019); wheelchair viewing platforms inspected; clear accessible path (min 36 inches) marked throughout all activation zones.', 'Pre-Event Route & Ramp Verification: Walk all accessible routes from public sidewalk to stage viewing areas; verify ramp slopes do not exceed 1:12; verify zero lip thresholds >0.25 in.', 'Elevated Viewing Platform Setup: Configure ADA viewing riser with code-compliant handrails, edge protection kick plates, and paired companion chairs with unobstructed sightlines.', 'Assisted Listening & Sensory Kit Distribution: Inspect RF assisted listening receivers and neck loops; stage sensory kits (noise-canceling headphones, sunglasses) at FOH guest desk.', 'Accessible Egress Escort & Dedicated Exit Clearance: During show egress, position dedicated guest ambassadors along primary ramp routes to ensure unimpeded wheelchair flow to rideshare hub.', 'DOC-019', 'Active', false, '2010 ADA Standards for Accessible Design & Florida Accessibility Code protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (21, 'SOP-020', 'Radio Frequency (RF) Spectrum Coordination & Wireless Intercom Intermodulation', 'Communications Infrastructure & Spectrum Control', 'v1.5', null, null, '9000 Technology', '9000.03.01', 'Two-Way Radios', '9000.52.01', 'TAG-033 FCC · TAG-034 FCC_PART74 · RF Analyzer Wand, High-Fidelity Test Headphones', 'FCC Part 74 license active (DOC-020); RF spectrum analyzer calibrated; Shure Wireless Workbench environment loaded with Miami broadcast exclusions.', 'Wideband Spectrum Sweep (470-608 MHz): Perform RF spectrum sweep across Wynwood venue airspace; identify active DTV broadcast channels and unauthorized rogue transmitters.', 'Intermodulation Calculation & Frequency Deployment: Compute intermodulation distortion profiles; coordinate compatible frequencies for 16x wireless mics and 8x IEM transmitters.', 'Axient Digital ShowLink & FreeSpeak Pairing: Deploy networked antenna distro (distro4); pair digital transmitters via IR sync; verify ShowLink automated interference avoidance.', 'Walk-Test RF Coverage & Shadow Mapping: Walk venue boundaries with test transmitter; verify zero dropouts across sanctuary, stage, and BOH green rooms; log RF stability report.', 'DOC-020', 'Active', false, 'FCC Part 74 Subpart H & AES recommended wireless audio frequency coordination protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (22, 'SOP-021', 'Generator Diesel Fueling, Spill Containment & Secondary HazMat Handling', 'Hazardous Materials & Fuel Safety', 'v1.0', null, null, '6000 Operations', '6000.09.01', 'Waste Management', '5000.50.02', 'TAG-002 OSHA · TAG-040 EPA · Chemical Nitrile Gloves, Safety Splash Goggles, Fuel-Resistant Apron', 'Environmental containment plan active (DOC-021); 55-gallon universal spill kit staged within 15 ft of fuel port; fire extinguisher (20BC) charged on post.', 'Pre-Fueling Ground Berm & Pad Inspection: Inspect secondary containment berm under 400A diesel generator; verify rubber liner intact with zero tears, water, or oil residue.', 'Bonding & Static Ground Wire Attachment: Attach heavy-duty copper static bonding cable from fuel supply truck chassis to generator ground lug prior to opening fuel cap.', 'Monitored Delivery & Cam-Lock Tightness: Execute controlled fuel pumping at low velocity (<25 GPM); monitor mechanical sight gauge; stop transfer at 90% tank capacity.', 'Nozzle Capping & Containment Log Clearance: Wipe fuel nozzle; disconnect bonding clamp; inspect spill berm for drips; record delivered gallons and date into HazMat binder.', 'DOC-021', 'Active', false, 'EPA SPCC Rule 40 CFR 112 & Miami-Dade DERM temporary fuel transfer protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (23, 'SOP-022', 'Commercial Insurance Endorsement Verification & Subcontractor COI Audit', 'Risk Governance & Insurance Compliance', 'v1.0', null, null, '0000 Executive', '0000.06.01', 'Insurance', '0000.51.01', 'None Required (Administrative Governance)', 'Master insurance binder bound (DOC-022); contract vendor roster active; digital COI tracking ledger online.', 'ACORD 25 Certificate Intake: Ingest all incoming vendor Certificates of Insurance; verify policy effective dates encompass entire load-in, event, and load-out window.', 'Coverage Limit & Endorsement Audit: Confirm minimum $1M Occurrence / $2M Aggregate GL limits; verify $5M Umbrella, Statutory Workers'' Comp, and $1M Commercial Auto.', 'Additional Insured Endorsement Scrutiny: Verify mandatory endorsement CG 20 26 or equivalent naming GHXSTSHIP, Spotify, and Venue Owner as Additional Insureds with Waiver of Subrogation.', 'Gate 2 Clearance & Vendor Access Lockout: Mark vendor insurance status ''Approved'' in Procurement Catalog; issue digital pass to dock master; lock out unapproved subcontractors.', 'DOC-022', 'Active', false, 'Commercial insurance risk underwriting standards & ACORD document verification protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (24, 'SOP-023', 'Aerial Work Platform (AWP) Operation, MEWP Inspection & Fall Arrest Protocols', 'Fall Protection & High-Altitude Safety', 'v2.1', null, null, '5000 Production', '5000.05.02', 'Rigging Hardware', '5000.51.02', 'TAG-002 OSHA · ANSI A92.20 Full-Body Fall Arrest Harness, Shock-Absorbing Lanyard, Hard Hat with Chinstrap', 'Fall protection plan active (DOC-023); certified MEWP operators rostered; ground drop-zone barricades staged.', 'Pre-Operation MEWP Walkaround: Perform daily pre-start inspection on scissor lift and articulating boom lift; test ground/basket emergency stop controls and hydraulic lines.', 'Fall Restraint Lanyard Anchorage: Prior to raising platform, attach harness lanyard to designated engineered anchor point inside basket; confirm 100% tie-off compliance.', 'Ground Perimeter Drop-Zone Lockout: Establish physical stanchions and red warning tape directly below elevated work basket; position ground spotter with whistle.', 'Elevated Maneuver & Overhead Clearance: Operate platform smoothly at crawl speed; maintain minimum 10-ft clearance from overhead building utilities, beams, and HVAC ducts.', 'DOC-023', 'Active', false, 'OSHA 1926.453 & ANSI/SAIA A92.22 safe use of mobile elevating work platforms (MEWPs).', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (25, 'SOP-024', 'Structural Rigging Hardware Proof-Testing & Beam Clamp Installation', 'Structural & Rigging Safety', 'v1.0', null, null, '5000 Production', '5000.05.02', 'Rigging Hardware', '5000.51.03', 'TAG-002 OSHA · TAG-022 ETCP · Hard Hat, Steel-Toe Boots, Heavy Leather Rigging Gloves, Fall Harness', 'Structural proof pull-test cert on file (DOC-024); stamped rigging plot DOC-004 approved; torque wrench calibrated.', 'Visual Hardware Grade Inspection: Inspect all 5/8-in Crosby shackles, G-100 master links, wire rope slings, and polyester Spansets; verify zero elongation, cuts, or heat damage.', 'Engineered Beam Clamp Placement: Mount forged steel beam clamps to approved structural I-beams per stamped plot; torque clamp locking nuts to manufacturer specified foot-pounds.', 'Secondary Safety Choker Rigging: Rig independent wire rope safety secondary choker around building structural beam node; mouse all shackle pins with stainless safety wire.', 'Test Pull & Load Cell Zeroing: Hang calibrated digital wireless load cell from hook; perform test pull; zero load cell before pinning truss bridles; log static tare weights.', 'DOC-024', 'Active', false, 'ANSI ES1.6 & OSHA 1910.184 entertainment rigging hardware inspection and proof-testing.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (26, 'SOP-025', 'Live Show Stage Management, SMPTE Timecode Sync & Performer Handover', 'Stage Management & Live Production Control', 'v4.0', null, null, '9000 Technology', '9000.50.01', 'Show Control & Playback', '9000.50.01', 'Clear-Com Headset, Production Flashlight with Red Filter, Run of Show Binder', 'Master cue schedule active (DOC-025); SMPTE timecode sync generator locked (29.97 fps); artist green room escort in place.', 'Master Timecode Clock Lock: Verify SMPTE linear timecode lock across playback DAWs, grandMA3 lighting desks, and disguise d3 media servers; confirm zero frame drift.', 'Talent Escort & Mic Sanitization (T-00:20): Escort headline artist from dressing room to stage left; fit sanitized wireless handheld mic and test custom IEM mix with A2.', 'Standby Call Sequence (T-00:02): Issue verbal countdown on Comms Ch A & B: ''Standby Top of Show, Standby Lighting Look 01, Standby Video Blade 01, Standby Audio Playback''.', 'Show Trigger GO & Live Changeover: Call crisp ''GO'' trigger precisely at 20:00:00; monitor live performance telemetry; oversee seamless 8-minute DJ to live band changeover.', 'DOC-025', 'Active', false, 'Production stage management and SMPTE timecode synchronization live execution protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (27, 'SOP-026', 'Solid Waste Diversion, Compost Sorting & Post-Event Site Sanitation', 'Environmental Sustainability & Waste Operations', 'v1.0', null, null, '6000 Operations', '6000.09.01', 'Waste Management', '6000.51.01', 'TAG-002 OSHA · Heavy-Duty Nitrile Cleaning Gloves, Steel-Toe Boots, High-Vis Vest, Safety Glasses', 'Waste diversion plan active (DOC-026); dual-stream recycling/trash pairs staged; compost dumpster spotted in yard.', 'Pre-Event Waste Station Deployment: Position co-located 3-stream waste stations (Compost, Clean Recycling, Landfill) every 25 ft across sanctuary and patio with visual signage.', 'Live Shift Monitoring & Bin Turnaround: Rove public areas; empty bins before reaching 75% capacity; replace with color-coded biodegradable liners; haul bags to rear compactor.', 'Post-Event Floor Magnetic & Mechanical Sweep: Following patron egress, execute rolling magnet sweep across lawn/patio for metal fasteners; complete wet mop of polished concrete floors.', 'Waste Stream Weighing & Diversion Reporting: Record weights of compost, single-stream recyclables, and landfill haul; compute event diversion percentage for sustainability report.', 'DOC-026', 'Active', false, 'Zero-waste event certification & LEED temporary event waste diversion protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (28, 'SOP-027', 'Temporary Potable Water Plumbing, Backflow Prevention & Disinfection', 'Water Distribution & Plumbing Hygiene', 'v1.0', null, null, '6000 Operations', '6000.06.04', 'Water & Plumbing', '4000.51.01', 'TAG-002 OSHA · NSF Food-Grade Rubber Gloves, Safety Glasses, Pipe Wrenches', 'Backflow inspection cert active (DOC-027); certified reduced pressure backflow preventer (RPBP) mounted; potable NSF-61 hoses sanitized.', 'Source Tie-In & Backflow Assembly Installation: Connect primary water supply to municipal spigot; install tested RPBP backflow preventer; verify zero cross-contamination.', 'Distribution Line Chlorination & Flush: Flush temporary potable distribution lines with 50 ppm chlorine solution for 24 hours; flush with fresh water until residual chlorine <0.5 ppm.', 'Potable Water Distribution & Pressure Regulation: Connect NSF-61 certified food-grade hoses to catering prep trailers, beverage carts, and handwash sinks; regulate pressure to 45 PSI.', 'Daily Water Quality Sampling & Drain Inspection: Conduct daily chlorine and bacterial dip test; inspect gray water collection tanks; schedule pump-out truck before tanks reach 80%.', 'DOC-027', 'Active', false, 'IPC Section 608 & Miami-Dade WASD temporary potable water distribution protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (29, 'SOP-028', 'RFID / NFC Credential Issuance, Zone Access Encoding & Anti-Passback Validation', 'Credentialing Systems & Access Security', 'v2.0', null, null, '7000 Experience', '7000.50.02', 'Credentials', '7000.50.02', 'None Required (Administrative / Tech)', 'Credential security matrix approved (DOC-028); encrypted RFID wristbands in vault; Zebra RFID badge printers online.', 'Master Credential Database Sync: Ingest approved personnel roster and VIP guest list into access management server; assign unique encrypted UID per record.', 'RFID Wristband Encoding & Physical Verification: Encode 13.56 MHz NFC wristband chips with tier permissions (All-Access, VIP, Production, GA); visually inspect tamper-evident clasp.', 'Turnstile Validation & Anti-Passback Enforcement: Configure optical turnstiles and handheld scanners with 15-minute anti-passback rule; verify sub-second scan validation latency.', 'Real-Time Attendance Headcount Monitoring: Track live scan feeds to maintain real-time occupant counts per zone; alert security if sanctuary approaches 350 occupant cap.', 'DOC-028', 'Active', false, 'ISO/IEC 14443 & PCI compliance event access credentialing protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (30, 'SOP-029', 'Marshalling Yard Loading Dock Traffic Management, Forklift & Rig Staging', 'Logistics Operations & Loading Dock Safety', 'v2.2', null, null, '6000 Operations', '6000.02.01', 'Forklifts & Loaders', '6000.51.02', 'TAG-002 OSHA · TAG-018 ANSI · Steel-Toe Boots, High-Vis Vest, Hard Hat, Work Gloves, Radio (Channel 3)', 'Dock booking schedule locked (DOC-029); certified forklift operators on call; yellow jacket cable ramps installed across traffic lane.', 'Carrier Arrival Check-In & Yard Spotting: Check in carrier trucks at marshalling gate; verify seal numbers against manifest; assign designated trailer staging bay.', 'Loading Dock Safety Sequence: Position trailer at Dock 1; engage tractor spring brakes; set dual rubber wheel chocks; lower trailer support stabilizing jacks.', 'Forklift Unloading & Floor Load Distribution: Unload heavy rigging road cases using 5,000-lb forklift; distribute weight evenly across dock floor; maintain clear 8-ft aisleways.', 'Dock Clearance & Carrier Release Sign-Off: Clear empty pallets and dunnage; inspect trailer floor for damage; sign carrier Bill of Lading with time stamp; dispatch carrier.', 'DOC-029', 'Active', false, 'OSHA 1910.178 powered industrial trucks and loading dock freight safety procedures.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (31, 'SOP-030', 'Temporary HVAC Spot Cooler Deployment, Ducting & Condensate Management', 'Climate Control & Environmental Engineering', 'v1.2', null, null, '4000 Environment', '4000.51.02', 'Climate Control', '4000.51.01', 'TAG-002 OSHA · Safety Glasses, Work Gloves, ANSI Steel-Toe Boots', 'HVAC load calculation on file (DOC-030); 208V 3-phase power drop verified; spot coolers staged in BOH corridor.', 'Spot Cooler Placement & Power Verification: Position 5-ton spot coolers in designated cooling nodes; connect 50A twist-lock power cables; verify proper phase rotation.', 'Flexible Ducting Run & Supply Air Balancing: Route 12-inch insulated flexible supply ducts to audience hot zones and stage wings; secure duct runs with zip ties and aircraft cable.', 'Condensate Pump & Drainage Routing: Connect automatic condensate sump pumps to drainage tubing; route discharge lines to sanitary sewer drain; test float switch cutoff.', 'Thermostat Calibration & Thermal Load Monitoring: Set digital thermostats to maintain 72 deg F ambient / 50% relative humidity; monitor server rack and LED wall exhaust zones.', 'DOC-030', 'Active', false, 'ASHRAE Standard 55 & Florida Mechanical Code temporary event cooling protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (32, 'SOP-031', 'Talent Hospitality Advancing, Green Room Security & Rider Execution', 'Artist Production & Hospitality Management', 'v1.0', null, null, '2000 Talent', '2000.03.01', 'Advancing', '2000.50.02', 'Artist Relations Access Lanyard, Production Radio (Channel 4)', 'Countersigned talent contract on file (DOC-031); rider fulfillment items procured; green room lockbox combination set.', 'Green Room Space Preparation & Inspection: Deep clean artist green room; stage requested FF&E (couches, mirrors, garment steamer); verify private restroom stocked and locked.', 'Rider Food & Beverage Fulfillment: Stock rider-specified beverages, organic snacks, and local specialty provisions; verify strict adherence to dietary restrictions and allergies.', 'Green Room Access Security Lockout: Post security officer outside artist dressing room suite; enforce strict closed-door policy; permit access only to badge-verified roster.', 'Artist Settlement & Sign-Off Documentation: Review hospitality receipts with artist road manager; confirm cash per-diems disbursed; obtain countersigned settlement voucher.', 'DOC-031', 'Active', false, 'GHXSTSHIP talent advancing standards and artist hospitality execution procedure.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (33, 'SOP-032', 'Incident Command CAD Logging, Mass Notification & AHJ Escalation', 'Crisis Communications & Incident Command', 'v2.0', null, null, '6000 Operations', '6000.05.01', 'Incident Management', '6000.50.02', 'Clear-Com Headset, Mobile CAD Dispatch Tablet, Radio (Channel 1)', 'Emergency Action Plan active (DOC-032); multi-channel radio matrix active; direct dispatch link to Miami 911 PSAP.', 'CAD Incident Ingest & Verification: Receive incident report on Radio Ch 1; record exact timestamp, location code (LOC-xx), reporting party, and severity level in CAD log.', 'Tactical Resource Dispatch: Dispatch nearest security officer, EMT team, or technical lead based on incident class; maintain active timer on response milestone.', 'Mass Notification Alert Triggering: In event of major life safety emergency, activate pre-recorded audio/visual evacuation message across all PA clusters and LED displays.', 'AHJ Briefing & Incident Debrief Closure: Coordinate on-site briefing with responding Miami Fire/Police commanders; document resolution notes and witness statements; close ticket.', 'DOC-032', 'Active', false, 'FEMA NIMS Incident Command System & NFPA 3000 emergency operations procedure.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (34, 'SOP-033', 'Environmental Scent Diffusion Nebulization & Fragrance Safety Control', 'Sensory Design & Atmosphere Management', 'v1.1', null, null, '7000 Experience', '7000.04.01', 'Scent Diffusion', '7000.50.01', 'Nitrile Handling Gloves, Safety Glasses', 'IFRA compliance safety data sheet active (DOC-033); cold-air nebulizers installed; botanical aroma cartridges stocked.', 'Cartridge Ingest & IFRA Batch Verification: Inspect aroma oil cartridges; verify IFRA safety certificates and batch numbers; ensure 100% hypoallergenic, phthalate-free oil.', 'Nebulizer Installation & HVAC Ducted Interface: Install cold-air diffusion units in primary air handler supply plenums; calibrate sub-micron droplet atomization.', 'Daypart Intensity Programming: Program digital diffusion duty cycles: 20% intensity for daytime arrival, 45% for evening reception, 10% during high-energy performance.', 'Sensory Air Quality Monitoring: Inspect venue air quality; ensure zero visible haze or oil residue on surfaces; log guest feedback and adjust fragrance concentration.', 'DOC-033', 'Active', false, 'IFRA Standards & OSHA indoor air quality environmental fragrancing protocol.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date),
  (35, 'SOP-034', 'Post-Event Venue Space Handover, Damage Inspection & Landlord Sign-Off', 'Facility Restoration & Space Handover', 'v1.0', null, null, '0000 Executive', '0000.50.04', 'Close Activities', '0000.50.01', 'High-Vis Vest, Flashlight, Digital Camera / Tablet', 'Architectural site CAD on file (DOC-034); pre-lease baseline photographic survey on file; strike completed (SOP-008).', 'Joint Architectural Walkthrough: Conduct comprehensive physical walk of sanctuary, patio, mezzanine, and parking facilities with building owner / landlord representative.', 'Photographic Punch List Generation: Photograph all surfaces, doors, glazing, and electrical tie-in panels; document any pre-existing vs event-related wear or marks.', 'Immediate Restoration Remediation: Deploy facilities maintenance technician to patch minor drywall blemishes, paint scuffs, or replace blown utility light bulbs.', 'Formal Handover Sign-Off & Security Deposit Release: Execute countersigned space release and condition certificate; submit documentation to finance for security bond return.', 'DOC-034', 'Active', false, 'Commercial lease surrender and post-production venue restoration sign-off procedure.', 'Julian Clarkson', '2026-10-02T09:54:54'::timestamp, '2026-10-02'::date);
